#!/usr/bin/env node
/**
 * Cut a release: gate, build, verify the artifacts, publish.
 *
 *   npm run release -- --dry-run     # everything except publishing
 *   npm run release                  # publish v<package.json version>
 *   npm run release -- --skip-build  # reuse whatever is in dist/
 *
 * ## Why this is a script and not a GitHub Actions workflow
 *
 * Three reasons, and the first is decisive.
 *
 * **CI has no station catalog.** `data/stations.min.json` is generated by the
 * crawl and gitignored, so a runner would package an app with no stations in it —
 * a 124 MB DMG that opens to an empty globe. Having CI run the crawl instead
 * would fire 12,296 requests at radio.garden on every release, and this project
 * has already knocked three KiwiSDRs offline by over-probing. Borrowed
 * infrastructure is not a build step.
 *
 * **The icon generator needs a real display.** `make-icons.js` drives Electron
 * and photographs a rendered page, and it now refuses to write a flat icon. On a
 * headless runner that check would fail the build correctly and endlessly.
 *
 * **Signing and notarization need the Mac anyway.** Once #4 lands, the certificate
 * lives in a keychain on this machine.
 *
 * So: a Mac builds, this script verifies what came out, and `gh` publishes it.
 *
 * ## What it verifies before publishing, and why each one
 *
 * The audit checks the source. This checks the *artifact*, because the two are
 * different questions and only one of them is what a stranger downloads. Every
 * item below is something that has actually been wrong in a built bundle at least
 * once in this project's history.
 */
import { execFileSync, spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const R = (p) => path.join(ROOT, p);
const DIST = R("dist");

const argv = process.argv.slice(2);
const dryRun = argv.includes("--dry-run");
const skipBuild = argv.includes("--skip-build");

const pkg = JSON.parse(fs.readFileSync(R("package.json"), "utf8"));
const VERSION = pkg.version;
const TAG = `v${VERSION}`;

let failed = false;
const ok = (m) => console.log(`  ok    ${m}`);
const bad = (m) => { failed = true; console.log(`  FAIL  ${m}`); };
const note = (m) => console.log(`  --    ${m}`);
const head = (m) => console.log(`\n${m}`);

const run = (cmd, args, opts = {}) =>
  execFileSync(cmd, args, { cwd: ROOT, encoding: "utf8", ...opts }).trim();
const quiet = (cmd, args) => { try { return run(cmd, args, { stdio: ["ignore", "pipe", "ignore"] }); } catch { return ""; } };
const stream = (cmd, args) => spawnSync(cmd, args, { cwd: ROOT, stdio: "inherit" });

// ── 1. is the tree fit to release from ───────────────────────────────────────
head(`Gate — releasing ${TAG}`);
{
  const branch = quiet("git", ["rev-parse", "--abbrev-ref", "HEAD"]);
  branch === "main" ? ok("on main") : bad(`on ${branch || "unknown"}, not main`);

  const dirty = quiet("git", ["status", "--porcelain"]);
  dirty ? bad(`working tree is dirty:\n${dirty.split("\n").map((l) => "          " + l).join("\n")}`)
        : ok("working tree clean");

  quiet("git", ["fetch", "origin", "--quiet"]);
  const ahead = quiet("git", ["rev-list", "--count", "origin/main..HEAD"]);
  const behind = quiet("git", ["rev-list", "--count", "HEAD..origin/main"]);
  (ahead === "0" && behind === "0")
    ? ok("in sync with origin/main")
    : bad(`${ahead} ahead, ${behind} behind origin/main — push or pull first`);

  // A tag that already exists means this version already shipped, or a previous
  // attempt got half way. Either way, stop rather than move a published tag.
  const tags = quiet("git", ["tag", "-l", TAG]);
  tags ? bad(`tag ${TAG} already exists — bump the version in package.json`) : ok(`tag ${TAG} is free`);

  const existing = quiet("gh", ["release", "view", TAG, "--json", "tagName"]);
  existing ? bad(`a GitHub release for ${TAG} already exists`) : ok(`no release for ${TAG} yet`);
}
if (failed) { console.log("\nGate failed. Nothing was built.\n"); process.exit(1); }

// ── 2. the source has to pass its own suite ──────────────────────────────────
head("Audit");
{
  const r = spawnSync("npm", ["run", "--silent", "audit"], { cwd: ROOT, encoding: "utf8" });
  if (r.status === 0) ok("all checks passed");
  else {
    console.log(r.stdout?.split("\n").filter((l) => /FAIL|failed/.test(l)).map((l) => "        " + l).join("\n"));
    bad("npm run audit failed");
  }
}
if (failed) { console.log("\nAudit failed. Nothing was built.\n"); process.exit(1); }

// ── 3. build ─────────────────────────────────────────────────────────────────
if (skipBuild) {
  head("Build");
  note("--skip-build: reusing whatever is in dist/");
} else {
  head("Build (vendor → notices → icons → both arches)");
  const r = stream("npm", ["run", "dist"]);
  if (r.status !== 0) { console.log("\nBuild failed.\n"); process.exit(1); }
}

// ── 4. verify what actually came out ─────────────────────────────────────────
head("Artifacts");
const dmgs = fs.existsSync(DIST)
  ? fs.readdirSync(DIST).filter((f) => f.endsWith(".dmg")).sort()
  : [];
{
  // Both architectures, because the x64 build is the one the hardware floor needs
  // and it is the one most likely to be silently dropped by a config change.
  const arm = dmgs.find((f) => f.includes("arm64"));
  const x64 = dmgs.find((f) => !f.includes("arm64"));
  arm ? ok(`arm64: ${arm}`) : bad("no arm64 DMG");
  x64 ? ok(`x64:   ${x64}`) : bad("no x64 DMG — this is the one the 2019 Intel Mac needs");

  for (const f of dmgs) {
    const mb = fs.statSync(path.join(DIST, f)).size / 1e6;
    // A DMG far under this means the asar lost something large — the catalog or
    // the Earth textures. Far over means something got in that should not.
    if (mb < 90) bad(`${f} is only ${mb.toFixed(0)} MB — something is missing`);
    else if (mb > 400) bad(`${f} is ${mb.toFixed(0)} MB — something got in that should not have`);
    else ok(`${f} is ${mb.toFixed(0)} MB`);
  }
}

const APP = path.join(DIST, "mac", "AuralFM.app");
const ASAR = path.join(APP, "Contents", "Resources", "app.asar");
{
  if (!fs.existsSync(ASAR)) bad("no app.asar to inspect");
  else {
    const list = quiet("npx", ["asar", "list", ASAR]).split("\n");
    // The reason this script exists rather than a CI workflow. If the catalog is
    // missing the app opens to an empty globe, and nothing else in the pipeline
    // would notice.
    const stations = list.find((l) => l.endsWith("data/packed/stations.min.json.gz"));
    stations ? ok("station catalog is inside app.asar") : bad("app.asar has NO station catalog");
    list.some((l) => l.endsWith("data/sdr.min.json"))
      ? ok("receiver bundle is inside app.asar") : bad("app.asar has no receiver bundle");
    list.some((l) => l.endsWith("THIRD-PARTY-NOTICES.md"))
      ? ok("licence notices are inside app.asar") : bad("app.asar has no THIRD-PARTY-NOTICES.md");
    list.some((l) => l.endsWith("docs/TERMS.md"))
      ? ok("terms are inside app.asar") : bad("app.asar has no docs/TERMS.md");
    list.some((l) => l.endsWith("assets/generated/dock-earth.png"))
      ? ok("app icons are inside app.asar") : bad("app.asar has no generated icons");
  }
}

// ── 5. signing, stated plainly ───────────────────────────────────────────────
head("Signing");
let signed = false, notarized = false;
{
  const cs = spawnSync("codesign", ["-dv", "--verbose=2", APP], { encoding: "utf8" });
  const out = `${cs.stdout || ""}${cs.stderr || ""}`;
  signed = /Authority=Developer ID Application/.test(out);
  const sp = spawnSync("spctl", ["-a", "-vv", APP], { encoding: "utf8" });
  notarized = /accepted/.test(`${sp.stdout || ""}${sp.stderr || ""}`);

  if (signed && notarized) ok("signed with a Developer ID and accepted by Gatekeeper");
  else if (signed) note("signed, but Gatekeeper has not accepted it — notarization missing");
  else {
    note("NOT signed and NOT notarized (#4)");
    note("Gatekeeper will refuse this on any other Mac. The release will be marked");
    note("as a prerelease and the notes will say so.");
  }
}

if (failed) { console.log("\nArtifacts failed verification. Nothing was published.\n"); process.exit(1); }

// ── 6. checksums — the only integrity signal an unsigned build has ───────────
head("Checksums");
const sums = [];
for (const f of dmgs) {
  const h = crypto.createHash("sha256").update(fs.readFileSync(path.join(DIST, f))).digest("hex");
  sums.push(`${h}  ${f}`);
  ok(`${f}  ${h.slice(0, 16)}…`);
}
const SUMS = path.join(DIST, "SHA256SUMS.txt");
fs.writeFileSync(SUMS, sums.join("\n") + "\n");
ok(`wrote ${path.relative(ROOT, SUMS)}`);

// ── 7. notes ─────────────────────────────────────────────────────────────────
head("Release notes");
const prev = quiet("git", ["describe", "--tags", "--abbrev=0"]);
const range = prev ? `${prev}..HEAD` : "HEAD";
const log = quiet("git", ["log", range, "--no-merges", "--format=- %s"]);
const commitCount = log ? log.split("\n").length : 0;

const gatekeeper = signed && notarized ? "" : `
## ⚠️ This build is not signed

There is no Apple Developer ID yet (#4), so macOS Gatekeeper will refuse to open
this on first launch. Until that lands, opening it takes a deliberate step:

1. Download the DMG for your Mac — \`arm64\` for Apple silicon, the other for Intel.
2. Drag AuralFM to Applications.
3. **Right-click the app → Open**, then confirm. A double-click will not work.

If macOS still refuses, clear the quarantine flag:

\`\`\`
xattr -dr com.apple.quarantine /Applications/AuralFM.app
\`\`\`

**Verify what you downloaded first.** An unsigned build has no other integrity
signal, so the checksums below are it:

\`\`\`
shasum -a 256 -c SHA256SUMS.txt
\`\`\`
`;

const notes = `AuralFM ${VERSION} — a photoreal globe you listen to.

**38,342 internet radio stations** across 12,296 places in 227 countries, plus
roughly **837 borrowed KiwiSDR shortwave receivers**. macOS, Intel and Apple
silicon.

## Which file

| Mac | Download |
|---|---|
| Apple silicon (M1 and later) | \`AuralFM-${VERSION}-arm64.dmg\` |
| Intel | \`AuralFM-${VERSION}.dmg\` |
${gatekeeper}
## What it collects

Nothing. No account, no telemetry, no analytics, no crash reporting. The app has
no backend of its own — presence and chat ride other people's Nostr relays, and
both are off until you switch them on. See \`docs/PRIVACY.md\` in the app under
Settings → About.

AuralFM itself is proprietary and is not open source; the libraries it bundles are
open source under their own licences, reproduced in full under
Settings → About → Open source licences.

## Changes

${log || "- first release"}

---

Built locally on macOS: ${commitCount} commit${commitCount === 1 ? "" : "s"}${prev ? ` since ${prev}` : ""}.
${sums.length} artifact${sums.length === 1 ? "" : "s"}, checksums attached.
`;

const NOTES = path.join(DIST, "RELEASE-NOTES.md");
fs.writeFileSync(NOTES, notes);
ok(`${commitCount} commits since ${prev || "the beginning"}`);
ok(`wrote ${path.relative(ROOT, NOTES)}`);

// ── 8. publish ───────────────────────────────────────────────────────────────
head("Publish");
if (dryRun) {
  note("--dry-run: nothing was tagged, pushed or published");
  note(`would run: gh release create ${TAG} ${dmgs.join(" ")} SHA256SUMS.txt`);
  note(`           ${signed && notarized ? "as a full release" : "as a PRERELEASE (unsigned)"}`);
  console.log(`\nDry run complete. Notes are in ${path.relative(ROOT, NOTES)}.\n`);
  process.exit(0);
}

// The tag is created here rather than by hand so it can never name a different
// commit than the one that was just verified.
run("git", ["tag", "-a", TAG, "-m", `AuralFM ${VERSION}`]);
run("git", ["push", "origin", TAG]);
ok(`tagged and pushed ${TAG}`);

const args = ["release", "create", TAG,
  ...dmgs.map((f) => path.join(DIST, f)), SUMS,
  "--title", `AuralFM ${VERSION}`,
  "--notes-file", NOTES];
// Unsigned means most people cannot install it. Publishing that as a full release
// would be advertising something that does not work.
if (!(signed && notarized)) args.push("--prerelease");

const r = spawnSync("gh", args, { cwd: ROOT, stdio: "inherit" });
if (r.status !== 0) {
  console.log(`\nPublish failed. The tag ${TAG} exists — delete it before retrying:`);
  console.log(`  git tag -d ${TAG} && git push origin :refs/tags/${TAG}\n`);
  process.exit(1);
}
console.log(`\nReleased ${TAG}${signed && notarized ? "" : " as a prerelease (unsigned)"}.\n`);
